  diff -q '"\\
    <(gzip -cd \""'$f" | awk '"'state==0 {if("'$0 !~ /''^@/) exit 1; id=$0; sub(/''^@/,"",id); sub(/'"\\/[12]([[:space:]]|"'$)/,"",id); state=1; next} state==1 {if($0 ~ /''^'"\\+/){state=2; q=0; next} next} state==2 {q+=length("'$0); if(q==length(seq)){state=0}; next}'"' ) \\
